package fr.bonobo.coffremaison.data

import androidx.room.*
import kotlinx.coroutines.flow.Flow

@Entity(tableName = "projects") data class ProjectEntity(@PrimaryKey(autoGenerate = true) val id: Long = 0, val titleCipher: String, val category: String, val createdAt: Long = System.currentTimeMillis(), val updatedAt: Long = System.currentTimeMillis())
@Entity(tableName = "notes", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"], onDelete = ForeignKey.CASCADE)], indices = [Index("projectId")]) data class NoteEntity(@PrimaryKey(autoGenerate = true) val id: Long = 0, val projectId: Long, val titleCipher: String, val bodyCipher: String, val updatedAt: Long = System.currentTimeMillis())
@Entity(tableName = "attachments", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"], onDelete = ForeignKey.CASCADE)], indices = [Index("projectId")]) data class AttachmentEntity(@PrimaryKey(autoGenerate = true) val id: Long = 0, val projectId: Long, val displayNameCipher: String, val mimeTypeCipher: String, val localFileName: String, val addedAt: Long = System.currentTimeMillis(), val titleCipher: String? = null, val documentDate: Long? = null, val amountCents: Long? = null, val contractorCipher: String? = null)
@Dao interface CoffreDao { @Query("SELECT * FROM projects ORDER BY updatedAt DESC") fun projects(): Flow<List<ProjectEntity>>; @Query("SELECT * FROM projects ORDER BY updatedAt ASC") suspend fun projectsOnce(): List<ProjectEntity>; @Query("SELECT * FROM projects WHERE id=:id") suspend fun projectOnce(id:Long): ProjectEntity?; @Query("SELECT * FROM notes WHERE projectId=:id ORDER BY updatedAt ASC") fun notes(id:Long): Flow<List<NoteEntity>>; @Query("SELECT * FROM notes WHERE projectId=:id ORDER BY updatedAt ASC") suspend fun notesOnce(id:Long): List<NoteEntity>; @Query("SELECT * FROM attachments WHERE projectId=:id ORDER BY addedAt ASC") fun attachments(id:Long): Flow<List<AttachmentEntity>>; @Query("SELECT * FROM attachments WHERE projectId=:id") suspend fun attachmentsOnce(id:Long): List<AttachmentEntity>; @Insert suspend fun addProject(p:ProjectEntity):Long; @Insert suspend fun addNote(n:NoteEntity); @Insert suspend fun addAttachment(a:AttachmentEntity):Long; @Update suspend fun updateNote(n:NoteEntity); @Update suspend fun updateProject(p:ProjectEntity); @Update suspend fun updateAttachment(a:AttachmentEntity); @Delete suspend fun deleteNote(n:NoteEntity); @Delete suspend fun deleteAttachment(a:AttachmentEntity); @Delete suspend fun deleteProject(p:ProjectEntity) }
@Database(entities=[ProjectEntity::class, NoteEntity::class, AttachmentEntity::class], version=3, exportSchema=false) abstract class AppDatabase:RoomDatabase(){ abstract fun dao():CoffreDao }
